mapper.select:
SELECT FP1.FINPROD_MARKET_ID prodId, A.PROD_NAME prodName, B.TYPE_9 type9, A.DEC_DATE decDate, SUM(A.PROSPECTIVE_ECL) eclP1, ROUND(SUM(A.PROSPECTIVE_ECL) / SUM(A.EAD), 6) decRatioP1, SUM(A.EAD) - SUM(A.PROSPECTIVE_ECL) decBalanceP1, SUM(A.PRE_PROSPECTIVE_ECL) perEclP1, ROUND(SUM(A.PRE_PROSPECTIVE_ECL) / SUM(A.EAD), 6) perDecRatioP1, COUNT(DISTINCT A.ASSET_ID) bondCountP1, 0 eclP2, 0 decRatioP2, 0 decBalanceP2, 0 perEclP2, 0 perDecRatioP2, 0 bondCountP2, 0 eclP3, 0 decRatioP3, 0 decBalanceP3, 0 perEclP3, 0 perDecRatioP3, 0 bondCountP3 FROM ASSET_LOSS_RESULT A INNER JOIN FIN_PRODUCT_TYPE B ON A.ASSET_ID = B.FINPROD_ID LEFT JOIN FIN_PRODUCT FP1 ON A.PROD_ID = FP1.FINPROD_ID WHERE 1=1 AND A.STAGE = #{stage}
AND A.DEC_DATE = #{decDate}
AND A.PROD_ID = #{prodId}
AND B.TYPE_9 = #{type9}
GROUP BY FP1.FINPROD_MARKET_ID,A.PROD_NAME,B.TYPE_9,A.DEC_DATE
